import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = data[2:2 + r]
    k = 0
    for i in range(r):
        for j in range(c):
            ch = g[i][j]
            if ch == '@':
                si, sj = i, j
            elif 'a' <= ch <= 'f':
                k += 1
    full = (1 << k) - 1
    seen = [[[False] * (1 << k) for _ in range(c)] for _ in range(r)]
    seen[si][sj][0] = True
    q = deque([(si, sj, 0, 0)])
    while q:
        i, j, m, d = q.popleft()
        if m == full:
            print(d)
            return
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = i + di, j + dj
            if 0 <= a < r and 0 <= b < c:
                ch = g[a][b]
                if ch == '#':
                    continue
                nm = m
                if 'a' <= ch <= 'f':
                    nm |= 1 << (ord(ch) - 97)
                elif 'A' <= ch <= 'F' and not (m >> (ord(ch) - 65)) & 1:
                    continue
                if not seen[a][b][nm]:
                    seen[a][b][nm] = True
                    q.append((a, b, nm, d + 1))
    print(-1)

