cache = {}

def dist(src, dst, held):
    key = (src, dst, held)
    if key in cache:
        return cache[key]
    d = {src: 0}
    q = deque([src])
    res = -1
    while q:
        x = q.popleft()
        if x == dst:
            res = d[x]
            break
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
