def gen(rng):
    def build(r, c, wp, k, lp):
        if 1 + 2 * k > r * c:
            return None
        cells = [(i, j) for i in range(r) for j in range(c)]
        rng.shuffle(cells)
        g = [['#' if rng.random() < wp else '.' for _ in range(c)] for _ in range(r)]
        i, j = cells[0]
        g[i][j] = '@'
        for t in range(k):
            i, j = cells[1 + t]
            g[i][j] = chr(97 + t)
            if rng.random() < lp:
                i, j = cells[1 + k + t]
                g[i][j] = chr(65 + t)
        return f"{r} {c}\n" + '\n'.join(''.join(row) for row in g)

    tests = ["1 3\n@.a", "1 3\na.@", "2 3\n@#a\n.A.", "1 5\n@.A.a", "1 6\n@.aA.b", "2 2\n@a\nbB"]
    for _ in range(12):
        r, c = rng.randint(1, 5), rng.randint(2, 6)
        k = rng.randint(1, 3)
