        if t:
            tests.append(t)
    # snake corridor: single long path, keys d,e,f at the far end, locks A,B,C on the way
    def snake(r, c):
        g = [['.'] * c for _ in range(r)]
        path = []
        for i in range(r):
            cols = range(c) if i % 2 == 0 else range(c - 1, -1, -1)
            for j in cols:
                path.append((i, j))
            if i % 2 == 1 and i + 1 < r:
                pass
        for i in range(1, r, 2):
            for j in range(c):
                g[i][j] = '#'
            g[i][c - 1 if i % 4 == 1 else 0] = '.'
        return g, [p for p in path if g[p[0]][p[1]] == '.']
    g, path = snake(29, 30)
    L = len(path)
    g[path[0][0]][path[0][1]] = '@'
    for t, frac in enumerate((0.1, 0.25, 0.4)):
        i, j = path[int(L * frac)]
        g[i][j] = chr(97 + t)
        i, j = path[int(L * (frac + 0.12))]
        g[i][j] = chr(65 + t)
    for t in range(3):
        i, j = path[L - 1 - 3 * t]
        g[i][j] = chr(100 + t)
    tests.append(f"29 30\n" + '\n'.join(''.join(row) for row in g))
    for _ in range(3):
        tests.append(build(30, 30, rng.choice([0.05, 0.12, 0.2]), 6, 1.0))
    tests.append(build(30, 30, 0.0, 6, 1.0))
    return [t for t in tests if t]

